import{_ as e,o,c as t,a5 as r}from"./chunks/framework.BwlBv862.js";const p=JSON.parse('{"title":"Cloud アカウントにサインインする","description":"","frontmatter":{"title":"Cloud アカウントにサインインする","docId":"user.cloud.account","translationKey":"user.cloud.account","locale":"ja","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"02b7718e7fc7b2a53b68ee1c6e19e622608a6fdfc7eac553879c474ca69ea74b","translationRevision":"e1b72a8f3e8f5ab3f79d0dbcf3e9709e58093e6afc3c0ba4178433531bcc5fd6","order":10},"headers":[],"relativePath":"ja/user/cloud/account.md","filePath":"ja/user/cloud/account.md","lastUpdated":1794611623000}'),i={name:"ja/user/cloud/account.md"};function n(l,a,s,c,d,u){return o(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="sign-in-to-your-cloud-account" tabindex="-1">Cloud アカウントにサインインする <a class="header-anchor" href="#sign-in-to-your-cloud-account" aria-label="Permalink to &quot;Cloud アカウントにサインインする {#sign-in-to-your-cloud-account}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">目的と前提条件 <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;目的と前提条件 {#goal-and-prerequisites}&quot;">​</a></h2><p>デスクトップアプリを設定済み Cloud サービスに接続し、アカウントを使うカタログや共同操作を利用します。ネットワーク、システムブラウザー、正常な OS の認証情報ストアが必要です。Cloud なしでもローカル編集は使えます。Cloud セッションは TikTok LIVE の認証にはなりません。</p><h2 id="sign-in-and-verify-identity" tabindex="-1">サインインして本人情報を確認する <a class="header-anchor" href="#sign-in-and-verify-identity" aria-label="Permalink to &quot;サインインして本人情報を確認する {#sign-in-and-verify-identity}&quot;">​</a></h2><ol><li><strong>設定 → アカウント</strong> を開き、別のログインを始める前に現在の状態を確認します。</li><li><strong>ログイン</strong> を選びます。デスクトップがローカルのコールバック受信口を起動し、設定済みログインページをシステムブラウザーで開きます。</li><li>サービスのログインを完了して TikTools に戻ります。ブラウザーが開かない場合は、その試行用に表示されたログイン URL を使います。この URL は非公開にし、公に投稿しないでください。</li><li>サインイン済みになるまで待ち、非公開カタログやチームを開く前に表示名かメールアドレスを確認します。</li><li>エラーが出たらアカウントの診断詳細を開きます。未完了の試行は <strong>キャンセル</strong> で終了し、複数を同時に残さないでください。</li><li>共有 PC で使い終えたら <strong>ログアウト</strong> を選び、アカウント状態が変わったことを確認します。</li></ol><p>ネイティブホストがセッショントークンを扱い、OS の認証情報ストアに保存します。フロントエンドには秘密を含まない状態だけを保持します。安全な保存先が使えない場合に平文ファイルへ代替保存することはありません。データフォルダーをコピーしても、サインイン済みセッションは移せません。</p><h2 id="expected-result-and-status" tabindex="-1">期待される結果と提供状況 <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;期待される結果と提供状況 {#expected-result-and-status}&quot;">​</a></h2><p>Cloud 認証付きでビルドされたホストでは、ネイティブのサインイン、復元、サインアウトを利用できます。設定済みアカウントは再起動時に復元し、サービスで再検証できます。未設定・非対応のホストは TikTok Cookie を変更しても直りません。</p><p>ログインサービスの利用可否と実際のプロバイダー・プラットフォームでの動作は、配置されたサービスと端末に依存します。ローカル検証だけでは、本番の全ログイン経路の動作は証明できません。</p><h2 id="recovery" tabindex="-1">問題が起きたとき <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;問題が起きたとき {#recovery}&quot;">​</a></h2><p>キャンセル・期限切れなら古い試行を閉じてから新しく始めます。ネットワークやサービスのエラーでは診断コードを保持し、復旧後に再試行します。認証情報ストアのエラーでは OS の安全な保存機能を復旧してください。Bearer トークンを設定やサポートメッセージへ貼り付けないでください。明示的な同期は <a href="./changes.html">変更</a>、別途付与するアクセス権は<a href="./collaboration.html">共同操作</a> を参照します。</p><h2 id="operational-details" tabindex="-1">運用の詳細 <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;運用の詳細 {#operational-details}&quot;">​</a></h2><p>ログアウトは先にローカル資格情報・アカウント文脈を消し、サーバー失効を最善努力で試します。ログアウト表示はローカル削除を示し、通信失敗時の遠隔 token 失効は保証しません。サービスにセッション管理があれば利用します。既知アカウントの変更・終了前に Diagnostics を書き出します。その UI 履歴は消去されます。TikTok Cookie・遠隔ホストセッションは別 ID です。</p>',13)])])}const f=e(i,[["render",n]]);export{p as __pageData,f as default};
